<?php

namespace parallel;

use Closure;

/**
 * <div id="class.parallel-runtime" class="reference"> <h1 class="title">The parallel\Runtime class</h1>  <div class="partintro"><p class="verinfo">(0.8.0)</p>  <div class="section">    <h2 class="title">Runtime Objects</h2>    <p class="simpara">     Each runtime represents a single PHP thread, the thread is created (and bootstrapped) upon construction.     The thread then waits for tasks to be scheduled: Scheduled tasks will be executed FIFO and then the thread will resume waiting until     more tasks are scheduled, or it's closed, killed, or destroyed by the normal scoping rules of PHP objects.    </p>    <div class="warning"><strong class="warning">警告</strong>     <p class="simpara">      When a runtime is destroyed by the normal scoping rules of PHP objects, it will first execute all of the tasks that were scheduled,      and block while doing so.     </p>    </div>  </div>  <div class="section">    <h2 class="title">Runtime Bootstrapping</h2>    <p class="simpara">     When a new runtime is created, it does not share code with the thread (or process) that created it. This means it doesn't have the same     classes and functions loaded, nor the same autoloader set. In some cases, a very lightweight runtime is desirable because the tasks that     will be scheduled do not need access to the code in the parent thread. In those cases where the tasks do need to access the same code, it     is enough to set an autoloader as the bootstrap.    </p>    <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:      <span class="simpara">      preloading may be used in conjunction with parallel, in this case preloaded code is available without bootstrapping     </span>    </p></blockquote>  </div>  <div class="section" id="parallel-runtime.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="ooclass">      <span class="modifier">final</span>      <span class="modifier">class</span> <strong class="classname">parallel\Runtime</strong>     </span>     {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// Create </div>    <div class="constructorsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parallel-runtime.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>()</div><div class="constructorsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parallel-runtime.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$bootstrap</span></span>)</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// Execute </div>    <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parallel-runtime.run.php" class="methodname" style="color:#CC7832">run</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.closure.php" class="type Closure" style="color:#EAB766">Closure</a></span> <span class="parameter" style="color:#3A95FF">\$task</span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766">Future</span></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parallel-runtime.run.php" class="methodname" style="color:#CC7832">run</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.closure.php" class="type Closure" style="color:#EAB766">Closure</a></span> <span class="parameter" style="color:#3A95FF">\$task</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$argv</span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766">Future</span></span></div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// Join </div>    <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parallel-runtime.close.php" class="methodname" style="color:#CC7832">close</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parallel-runtime.kill.php" class="methodname" style="color:#CC7832">kill</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>   }</div>  </div> </div>    <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link parallel\Runtime::__construct} — Runtime Construction</li><li>{@link parallel\Runtime::run} — Execution</li><li>{@link parallel\Runtime::close} — Runtime Graceful Join</li><li>{@link parallel\Runtime::kill} — Runtime Join</li></ul></div>
 * 
 * Each runtime represents a single PHP thread, the thread is created (and bootstrapped) upon construction. The thread
 * then waits for tasks to be scheduled: Scheduled tasks will be executed FIFO and then the thread will resume waiting
 * until more tasks are scheduled, or it's closed, killed, or destroyed by the normal scoping rules of PHP objects.
 *
 * Warning: When a runtime is destroyed by the normal scoping rules of PHP objects, it will first execute all of the
 * tasks that were scheduled, and block while doing so.
 *
 * When a new runtime is created, it does not share code with the thread (or process) that created it. This means it
 * doesn't have the same classes and functions loaded, nor the same autoloader set. In some cases, a very lightweight
 * runtime is desirable because the tasks that will be scheduled do not need access to the code in the parent thread.
 * In those cases where the tasks do need to access the same code, it is enough to set an autoloader as the bootstrap.
 *
 * Note: preloading may be used in conjunction with parallel, in this case preloaded code is available without
 * bootstrapping
 */
final class Runtime
{
    /* Create */

    /**
 * <div id="parallel-runtime.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">parallel\Runtime::__construct</h1>  <p class="verinfo">(0.8.0)</p><p class="refpurpose"><span class="refname">parallel\Runtime::__construct</span> — <span class="dc-title">Runtime Construction</span></p> </div> <div class="refsect1 description" id="refsect1-parallel-runtime.construct-description">  <h3 class="title">说明</h3>  <div class="constructorsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>parallel\Runtime::__construct</strong></span>()</div>  <p class="simpara">   Shall construct a new runtime without bootstrapping.  </p>  <div class="constructorsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>parallel\Runtime::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$bootstrap</span></span>)</div>  <p class="simpara">   Shall construct a bootstrapped runtime.  </p> </div>  <div class="refsect1 parameters" id="refsect1-parallel-runtime.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">bootstrap</span></dt>    <dd>     <span class="simpara">      The location of a bootstrap file, generally an autoloader.     </span>    </dd>     </dl> </div> <div class="refsect1 exceptions" id="refsect1-parallel-runtime.construct-exceptions">  <h3 class="title">Exceptions</h3>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    Shall throw <span class="type" style="color:#EAB766">parallel\Runtime\Error</span> if thread could not be created   </p>  </div>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    Shall throw <span class="type" style="color:#EAB766">parallel\Runtime\Bootstrap</span> if bootstrapping failed   </p>  </div> </div></div>
 * 
     * Shall construct a new runtime without bootstrapping.
     * Shall construct a bootstrapped runtime.
     *
     * @param null|string $bootstrap The location of a bootstrap file, generally an autoloader.
     *
     * @throws Runtime\Error if thread could not be created
     * @throws Runtime\Error\Bootstrap if bootstrapping failed
     */
    public function __construct(?string $bootstrap = null) {}

    /* Execute */

    /**
 * <div id="parallel-runtime.run" class="refentry"> <div class="refnamediv">  <h1 class="refname">parallel\Runtime::run</h1>  <p class="verinfo">(0.8.0)</p><p class="refpurpose"><span class="refname">parallel\Runtime::run</span> — <span class="dc-title">Execution</span></p> </div> <div class="refsect1 description" id="refsect1-parallel-runtime.run-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>parallel\Runtime::run</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.closure.php" class="type Closure" style="color:#EAB766">Closure</a></span> <span class="parameter" style="color:#3A95FF">\$task</span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766">Future</span></span></div>  <p class="simpara">   Shall schedule <span class="parameter" style="color:#3A95FF">task</span> for execution in parallel.  </p>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>parallel\Runtime::run</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.closure.php" class="type Closure" style="color:#EAB766">Closure</a></span> <span class="parameter" style="color:#3A95FF">\$task</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$argv</span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766">Future</span></span></div>  <p class="simpara">   Shall schedule <span class="parameter" style="color:#3A95FF">task</span> for execution in parallel, passing <span class="parameter" style="color:#3A95FF">argv</span> at execution time.  </p> </div> <div class="refsect1 parameters" id="refsect1-parallel-runtime.run-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">task</span></dt>    <dd>     <span class="simpara">      A <span class="classname"><a href="https://php.net/manual/zh/class.closure.php" class="classname">Closure</a></span> with specific characteristics.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">argv</span></dt>    <dd>     <span class="simpara">      An <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> of arguments with specific characteristics to be passed to <span class="parameter" style="color:#3A95FF">task</span> at execution time.     </span>    </dd>     </dl> </div> <div class="refsect1 closure-characteristics" id="refsect1-parallel-runtime.run-closure-characteristics"> <h3 class="title">Task Characteristics</h3> <p class="para">  Closures scheduled for parallel execution must not:  </p><ul class="simplelist">   <li>accept or return by reference</li>   <li>accept or return internal objects (see notes)</li>   <li>execute a limited set of instructions</li>  </ul>  <p class="para">  Instructions prohibited in Closures intended for parallel execution are:  </p><ul class="simplelist">   <li>yield</li>   <li>use by-reference</li>   <li>declare class</li>   <li>declare named function</li>  </ul>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:   <span class="simpara">   Nested closures may yield or use by-reference, but must not contain class or named function declarations.  </span> </p></blockquote> <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:   <span class="simpara">   No instructions are prohibited in the files which the task may include.  </span> </p></blockquote> </div> <div class="refsect1 argv-characteristics" id="refsect1-parallel-runtime.run-argv-characteristics"> <h3 class="title">Arguments Characteristics</h3> <p class="para">  Arguments must not:  </p><ul class="simplelist">   <li>contain references</li>   <li>contain resources</li>   <li>contain internal objects (see notes)</li>  </ul>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    In the case of file stream resources, the resource will be cast to the file descriptor and passed as <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> where possible, this is unsupported on Windows.   </span>  </p></blockquote>  </div> <div class="refsect1 object-characteristics" id="refsect1-parallel-runtime.run-object-characteristics">  <h3 class="title">Internal Objects Notes</h3>  <p class="simpara">   Internal objects generally use a custom structure which cannot be copied by value safely, PHP currently lacks the mechanics to do this (without serialization)   and so only objects that do not use a custom structure may be shared.  </p>  <p class="simpara">   Some internal objects do not use a custom structure, for example <span class="classname"><a href="https://php.net/manual/zh/class.parallel-events-event.php" class="classname">parallel\Events\Event</a></span> and so may be shared.  </p>  <p class="simpara">   Closures are a special kind of internal object and support being copied by value, and so may be shared.  </p>  <p class="simpara">   Channels are central to writing parallel code and support concurrent access and execution by necessity, and so may be shared.  </p>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    A user class that extends an internal class may use a custom structure as defined by the internal class, in which case they cannot be copied by value safely,    and so may not be shared.   </p>  </div> </div> <div class="refsect1 returnvalues" id="refsect1-parallel-runtime.run-returnvalues">  <h3 class="title">返回值</h3>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    The return <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.parallel-future.php" class="type parallel\Future" style="color:#EAB766">parallel\Future</a></span> must not be ignored when the task contains a return or throw statement.   </p>  </div> </div> <div class="refsect1 exceptions" id="refsect1-parallel-runtime.run-exceptions">  <h3 class="title">Exceptions</h3>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    Shall throw <span class="type" style="color:#EAB766">parallel\Runtime\Error\Closed</span> if <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.parallel-runtime.php" class="type parallel\Runtime" style="color:#EAB766">parallel\Runtime</a></span> was closed.   </p>  </div>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    Shall throw <span class="type" style="color:#EAB766">parallel\Runtime\Error\IllegalFunction</span> if <span class="parameter" style="color:#3A95FF">task</span> is a closure created from an internal function.   </p>  </div>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    Shall throw <span class="type" style="color:#EAB766">parallel\Runtime\Error\IllegalInstruction</span> if <span class="parameter" style="color:#3A95FF">task</span> contains illegal instructions.   </p>  </div>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    Shall throw <span class="type" style="color:#EAB766">parallel\Runtime\Error\IllegalParameter</span> if <span class="parameter" style="color:#3A95FF">task</span> accepts or <span class="parameter" style="color:#3A95FF">argv</span> contains illegal variables.   </p>  </div>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    Shall throw <span class="type" style="color:#EAB766">parallel\Runtime\Error\IllegalReturn</span> if <span class="parameter" style="color:#3A95FF">task</span> returns illegally.   </p>  </div> </div></div>
 * 
     * Shall schedule task for execution in parallel, passing argv at execution time.
     *
     * @param Closure $task    A Closure with specific characteristics.
     * @param null|array $argv An array of arguments with specific characteristics to be passed to task at execution
     *                         time.
     *
     * ### Task Characteristics
     * -----------------------------------------------------------------------------------------------------------------
     * Closures scheduled for parallel execution must not:
     *  - accept or return by reference
     *  - accept or return internal objects (see notes)
     *  - execute a limited set of instructions
     *
     * Instructions prohibited in Closures intended for parallel execution are:
     *  - yield
     *  - use by-reference
     *  - declare class
     *  - declare named function
     *
     * Note: Nested closures may yield or use by-reference, but must not contain class or named function declarations.
     * Note: No instructions are prohibited in the files which the task may include.
     *
     * ### Arguments Characteristics
     * -----------------------------------------------------------------------------------------------------------------
     * Arguments must not:
     *  - contain references
     *  - contain resources
     *  - contain internal objects (see notes)
     *
     * Note: In the case of file stream resources, the resource will be cast to the file descriptor and passed as int
     *     where possible, this is unsupported on Windows
     *
     * ### Internal Objects Notes
     * -----------------------------------------------------------------------------------------------------------------
     * Internal objects generally use a custom structure which cannot be copied by value safely, PHP currently lacks
     *     the mechanics to do this (without serialization) and so only objects that do not use a custom structure may
     *     be shared.
     *
     * Some internal objects do not use a custom structure, for example @see \parallel\Events\Event and so may be
     *     shared. Closures are a special kind of internal object and support being copied by value, and so may be
     *     shared. Channels are central to writing parallel code and support concurrent access and execution by
     *     necessity, and so may be shared.
     *
     * Warning: A user class that extends an internal class may use a custom structure as defined by the internal
     *     class, in which case they cannot be copied by value safely, and so may not be shared.
     *
     * @return Future|null The return Future must not be ignored when the task contains a return or throw
     *     statement.
     *
     * @throws Runtime\Error\Closed if \parallel\Runtime was closed.
     * @throws Runtime\Error\IllegalFunction if task is a closure created from an internal function.
     * @throws Runtime\Error\IllegalInstruction if task contains illegal instructions.
     * @throws Runtime\Error\IllegalParameter if task accepts or argv contains illegal variables.
     * @throws Runtime\Error\IllegalReturn if task returns illegally.
     */
    public function run(Closure $task, ?array $argv = null): ?Future {}

    /* Join */

    /**
 * <div id="parallel-runtime.close" class="refentry"> <div class="refnamediv">  <h1 class="refname">parallel\Runtime::close</h1>  <p class="verinfo">(0.8.0)</p><p class="refpurpose"><span class="refname">parallel\Runtime::close</span> — <span class="dc-title">Runtime Graceful Join</span></p> </div> <div class="refsect1 description" id="refsect1-parallel-runtime.close-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>parallel\Runtime::close</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Shall request that the runtime shutsdown.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    Tasks scheduled for execution will be executed before the shutdown occurs.   </span>  </p></blockquote> </div> <div class="refsect1 exceptions" id="refsect1-parallel-runtime.close-exceptions">  <h3 class="title">Exceptions</h3>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    Shall throw <span class="type" style="color:#EAB766">parallel\Runtime\Error\Closed</span> if <span class="type" style="color:#EAB766">Runtime</span> was already closed.   </p>  </div> </div></div>
 * 
     * Shall request that the runtime shutsdown.
     * Note: Tasks scheduled for execution will be executed before the shutdown occurs.
     *
     * @throws Runtime\Error\Closed if Runtime was already closed.
     */
    public function close(): void {}

    /**
 * <div id="parallel-runtime.kill" class="refentry"> <div class="refnamediv">  <h1 class="refname">parallel\Runtime::kill</h1>  <p class="verinfo">(0.8.0)</p><p class="refpurpose"><span class="refname">parallel\Runtime::kill</span> — <span class="dc-title">Runtime Join</span></p> </div> <div class="refsect1 description" id="refsect1-parallel-runtime.kill-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>parallel\Runtime::kill</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Shall attempt to force the runtime to shutdown.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    Tasks scheduled for execution will not be executed, the currently running task shall be interrupted.   </span>  </p></blockquote>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    Internal function calls in progress cannot be interrupted.   </p>  </div> </div> <div class="refsect1 exceptions" id="refsect1-parallel-runtime.kill-exceptions">  <h3 class="title">Exceptions</h3>  <div class="warning"><strong class="warning">警告</strong>   <p class="simpara">    Shall throw <span class="type" style="color:#EAB766">parallel\Runtime\Error\Closed</span> if <span class="type" style="color:#EAB766">Runtime</span> was closed.   </p>  </div> </div></div>
 * 
     * Shall attempt to force the runtime to shutdown.
     *
     * Note: Tasks scheduled for execution will not be executed, the currently running task shall be interrupted.
     * Warning: Internal function calls in progress cannot be interrupted.
     *
     * @throws Runtime\Error\Closed if Runtime was closed.
     */
    public function kill(): void {}
}
